import { chromium, expect } from '@playwright/test';

const browser = await chromium.launch();
const context = await browser.newContext({
  viewport: { width: 1280, height: 720 },
  recordVideo: {
    dir: 'artifacts/videos',
    size: { width: 1280, height: 720 }
  }
});

const page = await context.newPage();
const pause = () => page.waitForTimeout(500);
await page.goto('http://localhost:3000');
await pause();
await expect(page.getByRole('heading', { name: /barebones chat/i })).toBeVisible();
await expect(page.getByText(/welcome to the barebones chat demo/i)).toBeVisible();
await page.getByRole('button', { name: /new chat/i }).click();
await pause();
await expect(page.getByText(/new chat ready/i)).toBeVisible();
await expect(page.getByText(/welcome to the barebones chat demo/i)).not.toBeVisible();
await expect(page.getByText(/no messages yet/i)).toBeVisible();
await page.getByRole('button', { name: /launch plan chat/i }).click();
await pause();
await expect(page.getByText(/saved chat loaded/i)).toBeVisible();
await expect(page.getByText(/welcome to the barebones chat demo/i)).toBeVisible();
await expect(page.getByLabel(/message/i)).toBeVisible();
await page.waitForTimeout(2500);

await context.close();
await browser.close();

import { chromium, expect } from '@playwright/test';

const browser = await chromium.launch();
const context = await browser.newContext({
  viewport: { width: 1280, height: 720 },
  recordVideo: {
    dir: 'artifacts/videos',
    size: { width: 1280, height: 720 }
  }
});

const page = await context.newPage();
const pause = () => page.waitForTimeout(500);
await page.goto('http://localhost:3000');
await pause();
await page.getByRole('button', { name: /new chat/i }).click();
await pause();
await page.getByLabel(/message/i).click();
await pause();
await page.getByLabel(/message/i).fill('Show me the launch plan');
await pause();
await page.getByRole('button', { name: /send/i }).click();
await pause();
await expect(page.getByText('Show me the launch plan')).toBeVisible();
await expect(page.getByText(/demo reply: here is a simple launch plan/i)).toBeVisible();
const transcript = page.getByRole('log', { name: /conversation transcript/i });
await expect.poll(async () => transcript.evaluate((element) => element.scrollTop + element.clientHeight >= element.scrollHeight)).toBe(true);
await page.waitForTimeout(2500);

await context.close();
await browser.close();

